BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;
-- em caso de erro: ROLLBACK;

-- arriscado: SELECT stock ... ; (aplicação calcula) ; UPDATE ... SET stock = 9

-- atômico
UPDATE products SET stock = stock - 1 WHERE id = 10 AND stock > 0;

-- ou travando a linha durante a transação
BEGIN;
SELECT stock FROM products WHERE id = 10 FOR UPDATE;
UPDATE products SET stock = stock - 1 WHERE id = 10;
COMMIT;

BEGIN;
SELECT id, payload FROM jobs
WHERE status = 'pending'
ORDER BY created_at
LIMIT 1
FOR UPDATE SKIP LOCKED;
-- processa e marca como concluído
UPDATE jobs SET status = 'done' WHERE id = :id;
COMMIT;

-- não usa o índice em created_at
SELECT * FROM orders WHERE DATE(created_at) = '2026-10-01';
-- usa
SELECT * FROM orders
WHERE created_at >= '2026-10-01' AND created_at < '2026-10-02';

-- índice de expressão para busca sem caixa
CREATE INDEX users_email_lower_idx ON users (lower(email));
